#!/usr/bin/env bun
/**
 * Guard: keep the product name "Behavior" on the agent-facing surface.
 *
 * The word "watcher" remains an internal engine/DB term, but must not appear in:
 *
 *   - MCP tool schemas, names, descriptions, or titles
 *   - ClientSDK discovery metadata, aliases, or namespace method names
 *   - the connector-sdk public reaction contract
 *   - server and web-client response types for shared public tool payloads
 *   - query_sql's queryable-relation allowlist (QUERYABLE_SCHEMA table names),
 *     which the unknown-table error enumerates verbatim to the caller
 *
 * TypeBox schema initializers are scanned under the core tool contracts and the
 * server's tool/type sources. Other source scans are deliberately limited to
 * files whose literals are rendered into MCP or ClientSDK discovery output.
 * Comments are ignored except in the published connector-sdk declaration file,
 * where JSDoc is part of the public contract.
 *
 * Internal identifiers such as `actingWatcherId`, DB table/column names, and
 * implementation comments remain allowed outside those exposed constructs.
 * Source only — never dist/ or tests.
 *
 * Run: bun scripts/check-exposed-surface-naming.ts
 */

import { readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import ts from "typescript";

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const BANNED = /watcher/i;
const BANNED_SNAKE_KEY = /^[a-z0-9_]*watcher[a-z0-9_]*$/;

type Violation = { file: string; line: number; excerpt: string };

function rel(abs: string): string {
  return relative(REPO_ROOT, abs);
}

function collectTsFiles(dir: string): string[] {
  const out: string[] = [];
  for (const name of readdirSync(dir)) {
    if (name === "__tests__" || name === "node_modules" || name === "dist") {
      continue;
    }
    const full = join(dir, name);
    const st = statSync(full);
    if (st.isDirectory()) {
      out.push(...collectTsFiles(full));
    } else if (
      name.endsWith(".ts") &&
      !name.endsWith(".test.ts") &&
      !name.endsWith(".d.ts")
    ) {
      out.push(full);
    }
  }
  return out;
}

function parse(file: string): ts.SourceFile {
  return ts.createSourceFile(
    file,
    readFileSync(file, "utf8"),
    ts.ScriptTarget.Latest,
    true,
    ts.ScriptKind.TS
  );
}

function addViolation(
  violations: Violation[],
  file: string,
  source: ts.SourceFile,
  node: ts.Node
): void {
  const start = node.getStart(source);
  const { line } = source.getLineAndCharacterOfPosition(start);
  const text = source.text.split("\n")[line]?.trim() ?? "";
  violations.push({
    file: rel(file),
    line: line + 1,
    excerpt: text.slice(0, 120),
  });
}

function isTemplateText(node: ts.Node): node is ts.TemplateLiteralLikeNode {
  return (
    ts.isNoSubstitutionTemplateLiteral(node) ||
    ts.isTemplateHead(node) ||
    ts.isTemplateMiddle(node) ||
    ts.isTemplateTail(node)
  );
}

function propertyName(node: ts.Node): ts.PropertyName | undefined {
  if (
    ts.isPropertyAssignment(node) ||
    ts.isPropertySignature(node) ||
    ts.isMethodSignature(node) ||
    ts.isMethodDeclaration(node) ||
    ts.isPropertyDeclaration(node) ||
    ts.isGetAccessorDeclaration(node) ||
    ts.isSetAccessorDeclaration(node)
  ) {
    return node.name;
  }
  return undefined;
}

function propertyNameText(name: ts.PropertyName): string | undefined {
  if (
    ts.isIdentifier(name) ||
    ts.isStringLiteral(name) ||
    ts.isNoSubstitutionTemplateLiteral(name)
  ) {
    return name.text;
  }
  return undefined;
}

/** Scan exposed literals and context-appropriate property names, excluding comments. */
function scanSyntaxNode(
  file: string,
  source: ts.SourceFile,
  root: ts.Node,
  violations: Violation[],
  allPropertyNamesAreExposed = false
): void {
  function visit(node: ts.Node): void {
    if (
      (ts.isStringLiteral(node) || isTemplateText(node)) &&
      BANNED.test(node.text)
    ) {
      addViolation(violations, file, source, node);
    }

    const name = propertyName(node);
    const text = name && propertyNameText(name);
    if (
      text &&
      (allPropertyNamesAreExposed
        ? BANNED.test(text)
        : BANNED_SNAKE_KEY.test(text))
    ) {
      addViolation(violations, file, source, name);
    }

    ts.forEachChild(node, visit);
  }

  visit(root);
}

function scanExposedSyntax(file: string, violations: Violation[]): void {
  const source = parse(file);
  scanSyntaxNode(file, source, source, violations);
}

function containsTypeBoxCall(root: ts.Node): boolean {
  let found = false;
  function visit(node: ts.Node): void {
    if (
      ts.isCallExpression(node) &&
      ts.isPropertyAccessExpression(node.expression) &&
      ts.isIdentifier(node.expression.expression) &&
      node.expression.expression.text === "Type"
    ) {
      found = true;
      return;
    }
    if (!found) ts.forEachChild(node, visit);
  }
  visit(root);
  return found;
}

/** Scan top-level declarations that construct TypeBox schemas, not handlers/SQL. */
function scanTypeBoxSchemas(file: string, violations: Violation[]): void {
  const source = parse(file);
  for (const statement of source.statements) {
    if (!ts.isVariableStatement(statement)) continue;
    for (const declaration of statement.declarationList.declarations) {
      const initializer = declaration.initializer;
      if (initializer && containsTypeBoxCall(initializer)) {
        scanSyntaxNode(file, source, initializer, violations, true);
      }
    }
  }
}

/**
 * Workspace packages whose types are part of the agent-facing surface. A
 * namespace signature reaches into these directly — `listCatalog(input?:
 * Omit<ListCatalogArgs, "action">)` imports `ListCatalogArgs` from
 * `@lobu/core/...` — so treating "not relative" as "not ours" would skip a
 * live wire contract. Third-party packages stay out of scope: node_modules is
 * not our surface to police.
 */
const WORKSPACE_ALIASES: ReadonlyArray<readonly [string, string]> = [
  ["@lobu/core/", join(REPO_ROOT, "packages/core/src/")],
  ["@lobu/connector-sdk/", join(REPO_ROOT, "packages/connector-sdk/src/")],
  ["@lobu/plugin-api/", join(REPO_ROOT, "packages/plugin-api/src/")],
];

/** Resolve an import specifier to a source file, relative or workspace-aliased. */
function resolveImport(
  fromFile: string,
  specifier: string
): string | undefined {
  let base: string | undefined;
  if (specifier.startsWith(".")) {
    base = resolve(dirname(fromFile), specifier);
  } else {
    for (const [prefix, root] of WORKSPACE_ALIASES) {
      if (specifier.startsWith(prefix)) {
        base = join(root, specifier.slice(prefix.length));
        break;
      }
    }
  }
  if (!base) return undefined;
  for (const candidate of [`${base}.ts`, join(base, "index.ts")]) {
    try {
      if (statSync(candidate).isFile()) return candidate;
    } catch {
      // Not this candidate; try the next.
    }
  }
  return undefined;
}

/**
 * Map every locally-imported type name to the file that defines it AND the name
 * it is declared under there.
 *
 * The distinction matters for aliased imports. `import type { AuthProfileKind
 * as StoredAuthProfileKind }` is referenced locally as `StoredAuthProfileKind`,
 * but the declaring module knows it as `AuthProfileKind` — looking up the local
 * alias in the target file finds nothing and silently gives up, which is
 * exactly how this guard kept passing on a banned member of an imported type.
 */
function importedTypeOrigins(
  file: string,
  source: ts.SourceFile
): Map<string, { file: string; exportedName: string }> {
  const origins = new Map<string, { file: string; exportedName: string }>();
  for (const statement of source.statements) {
    if (
      !ts.isImportDeclaration(statement) ||
      !ts.isStringLiteral(statement.moduleSpecifier)
    ) {
      continue;
    }
    const target = resolveImport(file, statement.moduleSpecifier.text);
    if (!target) continue;
    const bindings = statement.importClause?.namedBindings;
    if (!bindings || !ts.isNamedImports(bindings)) continue;
    for (const element of bindings.elements) {
      origins.set(element.name.text, {
        file: target,
        // `propertyName` is the name in the source module when aliased.
        exportedName: (element.propertyName ?? element.name).text,
      });
    }
  }
  return origins;
}

/** Find a named type/interface declaration at the top level of a file. */
function findTypeDeclaration(
  source: ts.SourceFile,
  name: string
): ts.Node | undefined {
  for (const statement of source.statements) {
    if (
      (ts.isInterfaceDeclaration(statement) ||
        ts.isTypeAliasDeclaration(statement)) &&
      statement.name.text === name
    ) {
      return statement;
    }
  }
  return undefined;
}

/**
 * ClientSDK namespace surface: `*Namespace` method names plus every property
 * name and string literal reachable from an exported type in the file — method
 * parameter and return types, nested type literals, exported input/output
 * declarations, and the definitions of types they reference.
 *
 * Recursion matters in two directions, and missing either one has already
 * shipped a false negative past an earlier revision of this guard:
 *
 *   - Depth: an agent-facing key is agent-facing at any depth, so
 *     `{ source: { watcher_id } }` and `method(input: { watcher_id })` are
 *     violations exactly like a top-level member.
 *   - Reference: `profile_kind: AuthProfileKind` puts whatever
 *     `AuthProfileKind` resolves to on the wire. Scanning only the current
 *     file let a banned member of an imported type pass clean, so type
 *     references are followed into their defining module (local paths only —
 *     node_modules is not our surface to police).
 *
 * String literals count here, not just property names: a referenced type is
 * frequently a union of wire values (`"watcher" | "behavior"`), which is
 * exposed vocabulary even though no property carries the word.
 */
function scanNamespaceSurface(file: string, violations: Violation[]): void {
  const seen = new Set<string>();

  function scanFile(currentFile: string, rootNames: string[] | null): void {
    let source: ts.SourceFile;
    try {
      source = parse(currentFile);
    } catch {
      return;
    }
    const imports = importedTypeOrigins(currentFile, source);

    function walk(node: ts.Node): void {
      const name = propertyName(node);
      const text = name && propertyNameText(name);
      if (name && text && BANNED.test(text)) {
        addViolation(violations, currentFile, source, name);
      }

      if (
        (ts.isStringLiteral(node) || isTemplateText(node)) &&
        BANNED.test(node.text)
      ) {
        addViolation(violations, currentFile, source, node);
      }

      // Follow `foo: SomeType` into SomeType's declaration, and `interface X
      // extends Y` into Y's — an inherited member is on the wire exactly like a
      // declared one, and `extends` is an ExpressionWithTypeArguments rather
      // than a TypeReferenceNode, so it needs naming separately.
      const referencedName = ts.isTypeReferenceNode(node)
        ? ts.isIdentifier(node.typeName)
          ? node.typeName.text
          : undefined
        : ts.isExpressionWithTypeArguments(node) &&
            ts.isIdentifier(node.expression)
          ? node.expression.text
          : undefined;
      if (referencedName) {
        const referenced = referencedName;
        const local = findTypeDeclaration(source, referenced);
        if (local) {
          const key = `${currentFile}#${referenced}`;
          if (!seen.has(key)) {
            seen.add(key);
            walk(local);
          }
        } else {
          const origin = imports.get(referenced);
          if (origin) scanFile(origin.file, [origin.exportedName]);
        }
      }

      ts.forEachChild(node, walk);
    }

    if (rootNames) {
      for (const name of rootNames) {
        const key = `${currentFile}#${name}`;
        if (seen.has(key)) continue;
        seen.add(key);
        const declaration = findTypeDeclaration(source, name);
        if (declaration) walk(declaration);
      }
      return;
    }

    for (const statement of source.statements) {
      const isNamespaceInterface =
        ts.isInterfaceDeclaration(statement) &&
        statement.name.text.endsWith("Namespace");
      const isExportedType =
        (ts.isInterfaceDeclaration(statement) ||
          ts.isTypeAliasDeclaration(statement)) &&
        statement.modifiers?.some(
          (modifier) => modifier.kind === ts.SyntaxKind.ExportKeyword
        );
      if (isNamespaceInterface || isExportedType) {
        walk(statement);
      }
    }
  }

  scanFile(file, null);
}

/**
 * query_sql's queryable-relation allowlist.
 *
 * BLIND SPOT THIS CLOSES: `QUERYABLE_SCHEMA` in
 * `packages/server/src/utils/table-schema.ts` is agent-facing vocabulary — the
 * allowlist error enumerates every relation name verbatim to the caller — but
 * `utils/` was in NO scanned directory, and the name reaches the agent through
 * a runtime `[...QUERYABLE_TABLE_NAMES].join(', ')` rather than a static
 * literal, so neither the directory scans nor the literal scans could have
 * seen it. `watchers` / `watcher_versions` were exposed to agents for the
 * entire life of this guard while it reported clean.
 *
 * Scanning the whole file would fire on every legitimate internal use (physical
 * table names in the CTE builder, `watcher_id` columns, comments). What is
 * agent-facing is precisely the `name:` of each entry in the
 * `QUERYABLE_SCHEMA.tables` array, so that is what is checked — the exposed
 * relation names only, not the physical mapping beside them.
 */
function scanQueryableRelationNames(
  file: string,
  violations: Violation[]
): void {
  const source = parse(file);

  function visit(node: ts.Node): void {
    if (
      ts.isVariableDeclaration(node) &&
      ts.isIdentifier(node.name) &&
      node.name.text === "QUERYABLE_SCHEMA" &&
      node.initializer &&
      ts.isObjectLiteralExpression(node.initializer)
    ) {
      for (const property of node.initializer.properties) {
        if (
          !ts.isPropertyAssignment(property) ||
          propertyNameText(property.name) !== "tables" ||
          !ts.isArrayLiteralExpression(property.initializer)
        ) {
          continue;
        }
        for (const entry of property.initializer.elements) {
          if (!ts.isObjectLiteralExpression(entry)) continue;
          for (const field of entry.properties) {
            if (
              ts.isPropertyAssignment(field) &&
              propertyNameText(field.name) === "name" &&
              ts.isStringLiteral(field.initializer) &&
              BANNED.test(field.initializer.text)
            ) {
              addViolation(violations, file, source, field.initializer);
            }
          }
        }
      }
    }
    ts.forEachChild(node, visit);
  }

  visit(source);
}

/** Published declaration text, including JSDoc. */
function scanFullText(file: string, violations: Violation[]): void {
  const lines = readFileSync(file, "utf8").split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i] ?? "";
    if (BANNED.test(line)) {
      violations.push({
        file: rel(file),
        line: i + 1,
        excerpt: line.trim().slice(0, 120),
      });
    }
  }
}

const violations: Violation[] = [];

// Public connector type declarations: JSDoc is published with the types.
scanFullText(
  join(REPO_ROOT, "packages/connector-sdk/src/reaction-client-types.ts"),
  violations
);

// TypeBox declarations that feed MCP and ClientSDK request/result schemas.
for (const dir of [
  join(REPO_ROOT, "packages/core/src/contracts/tools"),
  join(REPO_ROOT, "packages/server/src/tools"),
  join(REPO_ROOT, "packages/server/src/types"),
]) {
  for (const file of collectTsFiles(dir)) {
    scanTypeBoxSchemas(file, violations);
  }
}

// query_sql's queryable-relation allowlist: enumerated verbatim to agents in
// the unknown-table error, so the relation names are agent-facing vocabulary.
scanQueryableRelationNames(
  join(REPO_ROOT, "packages/server/src/utils/table-schema.ts"),
  violations
);

// Tool names/descriptions/titles and SDK discovery text/names/aliases.
for (const file of [
  join(REPO_ROOT, "packages/server/src/tools/registry.ts"),
  join(REPO_ROOT, "packages/server/src/tools/admin/index.ts"),
  join(REPO_ROOT, "packages/server/src/sandbox/method-metadata.ts"),
  join(REPO_ROOT, "packages/server/src/sandbox/sdk-aliases.ts"),
  join(REPO_ROOT, "packages/server/src/sandbox/sdk-manifest.ts"),
]) {
  scanExposedSyntax(file, violations);
}

// Runtime-callable ClientSDK namespace member names, plus the exported input /
// output types that describe their arguments — `watcher_id` on an exported
// namespace interface is an agent-facing wire key even though it is not a
// method name.
const namespacesDir = join(REPO_ROOT, "packages/server/src/sandbox/namespaces");
for (const file of collectTsFiles(namespacesDir)) {
  scanNamespaceSurface(file, violations);
}

// Plain TypeScript response types are not TypeBox initializers, but they still
// describe public tool payloads. Keep the server projection and the trusted web
// client's wire models under the same vocabulary gate so a generic
// Type.Record result cannot hide a stale key from the schema scan.
for (const file of [
  join(
    REPO_ROOT,
    "packages/server/src/tools/admin/manage_operations/activity-feed.ts"
  ),
  join(REPO_ROOT, "packages/owletto/src/lib/api/activity.ts"),
  join(REPO_ROOT, "packages/owletto/src/lib/api/behaviors.ts"),
  join(REPO_ROOT, "packages/owletto/src/lib/api/content.ts"),
  join(REPO_ROOT, "packages/owletto/src/lib/api/runs.ts"),
]) {
  scanNamespaceSurface(file, violations);
}

const seen = new Set<string>();
const unique = violations.filter((violation) => {
  const key = `${violation.file}:${violation.line}:${violation.excerpt}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});
unique.sort((a, b) => a.file.localeCompare(b.file) || a.line - b.line);

if (unique.length > 0) {
  console.error(
    `check-exposed-surface-naming: "watcher" is banned on the agent-facing surface ` +
      `(use Behavior / behavior_*). Found ${unique.length} occurrence(s):\n`
  );
  for (const violation of unique) {
    console.error(
      `  ${violation.file}:${violation.line}: ${violation.excerpt}`
    );
  }
  console.error(
    `\nScope: MCP tool schemas/descriptions, ClientSDK discovery and callable ` +
      `method names, public response types, and the reaction client types. Internal engine ` +
      `names outside exposed schema constructs remain allowed.`
  );
  process.exit(1);
}

console.log(
  "check-exposed-surface-naming: clean — no agent-facing 'watcher' on exposed surface."
);
# Server package agent rules

Read root `AGENTS.md` first. This package owns the gateway, auth, connections, feeds, orchestration, connector operations, guardrails, Slackbot MCP integration, and embedded runtime.

## Package-specific traps
Read before editing. Full list in `docs/GOTCHAS.md`; these bite most often here:
- This package is **biome-excluded**. Never run biome on it — edit surgically, matching each file's existing style. CI will not catch the reflow.
- The DB client sets `fetch_types: false`, so a raw JS array bound as a parameter always fails. CI enforces this via `scripts/check-raw-array-params.mjs`; see GOTCHAS "DB & SQL" for the safe binding forms before reaching for a workaround.
- Hoisted `vi.mock()` silently fails in the integration suite (shared module registry). Use `vi.resetModules()` + `vi.doMock()` + dynamic import, and verify by co-running sibling test files.
- Dropping a column from a queryable table is a two-phase change across two releases — `QUERYABLE_SCHEMA` emits explicit column lists.

## Boundaries and vocabulary
- Connections are rows, not processes. Agents bind to connections/channels; replicas hydrate connection instances on demand from DB rows and must not assume boot warm-start.
- Connectors collect external data into feeds/events; chat platforms deliver conversations/messages. Do not blur connector sync with chat transport.
- Behaviors are the UI umbrella: Listen, Watch, Schedule. A watcher owns windows; a window's living state is a canvas (`semantic_type='canvas_state'`). Artifacts are stored files, not watcher state.
- Platform isolation: InteractionService events carry `platform`; each renderer filters on its own platform and never another's.

## Connections, feeds, and routing
- Chat platforms live under `src/gateway/connections/` and use Chat SDK adapters. Configure connections via `/agents` UI or CRUD API; do not add per-platform env vars or bespoke SDK transports.
- Webhooks are the default transport. Telegram alone supports `auto|webhook|polling`; reject polling in cloud mode.
- `feeds` is the unified list. `kind='collected'` feeds are scheduled connector pulls into `events`; `kind='streaming'` feeds are chat channels backed by `channel_messages`, not scheduled syncs; `virtual` feeds are projections/metadata and must not be queued as real sync work.
- Runtime connection ids may be slugs/managed ids (for example `slackinst-…`), not numeric `connections.id`. Resolve through connection stores; do not cast runtime ids to bigint.
- Bound chat channels should materialize an idempotent streaming feed so the UI has one feed model, not a separate channel island.

## Auth, providers, and secrets
- Product auth uses better-auth/session/PAT flows in `src/auth`; model/provider auth and user auth profiles live under `src/gateway/auth`.
- Provider catalog/settings are org/user scoped. Do not hardcode provider credentials, base URLs, or model lists; resolve through the provider catalog/settings stores.
- Workers never see real credentials. The gateway secret/MCP proxies swap placeholders or inject OAuth/API credentials at egress.
- MCP servers come from per-agent settings or `SKILL.md`; workers discover tools at startup and call them through the gateway proxy.
- Device-pinned connectors are special: resolved connection credentials may be delivered only to the authorized device worker that owns that run.
- Connector-contributed agent tooling (`gateway/agent-tooling/`) is the other carve-out, and only for **leases**: a short-lived provider-derived token (GitHub App installation tokens, ~1h) minted per deployment and injected as a real env var. It expires on its own and is revocable at the provider without touching the stored credential, which never leaves the gateway. `credential: 'lease'` is the only tier — there is deliberately no static-credential tier, because the worker egress proxy raw-tunnels HTTPS CONNECT and cannot swap a placeholder inside TLS; a CLI would send the placeholder to the provider verbatim. Any other tier value is dropped, not defaulted. Never widen this to a durable stored credential.

  **Lifecycle limitation (v1):** a lease is minted at deployment time and the worker reads its env once at process start, so a WARM deployment keeps the credential it was born with. On a conversation that stays continuously active past the token's ~1h life, `gh` starts reporting itself unauthenticated; a connector connected mid-conversation likewise does not appear until the worker is rebuilt. Bounded by `WORKER_IDLE_CLEANUP_MINUTES` (default 60): any hour-long idle gap reaps the worker and the next turn mints fresh. Recycling a deployment before its lease or tooling goes stale is tracked separately — it is a concurrency-sensitive change (teardown must not interrupt a live turn, and the message path only sees deployments its own pod owns), which is why it is not folded in here. Credentials, egress domains, and declared nix packages reach EVERY runtime: remote runtimes provision the packages from the signed `nixPackages` claim via the provider's optional `ensurePackages` (see the nix bullet under "Guardrails, network, and runtime"). A provider that implements no `ensurePackages` is the one case that still gets the credential plus whatever tools its image ships.

## Multi-replica correctness
- Production can run N>1 replicas. Before claiming a feature works, ask: “does this hold with 3 replicas?” Correctness must not depend on session affinity.
- Per-pod state (`SseManager`, event backlog, in-process worker map, deploy-lock cache) is pod-local. Cross-replica delivery must use Postgres (`thread_response` queue or equivalent).
- API/SSE terminal rows and interaction cards are owner-routed; non-owners requeue until the owning pod claims. Headless rows with no SSE client may be delivered by first claim.
- Streaming deltas/status are best-effort across pods today. Do not build correctness on cross-pod in-memory delivery.
- Exclusive transports such as Telegram polling run on exactly one replica via `connection_claims`; webhook transports must run on any replica.

## Connector operations and feed health
- Built-in connector definitions/catalog install in server; connector implementation details belong in `packages/connectors/AGENTS.md`.
- Connector health scans `connections` + `feeds`; chat connections are not collector connections and should not trip zero-feed collector health rules.
- Feed hard auto-pause emits `feed.auto_paused` (Behavior signal + lifecycle event). Prefer a normal Behavior over new special-case agent subsystems.

## Guardrails, network, and runtime
- Guardrails live under `packages/core/src/guardrails/`; server built-ins/aggregation live under gateway guardrail code. Guardrail infra errors fail open; each trip writes a `guardrail-trip` event.
- Worker HTTP(S) egress goes through the authenticated gateway proxy plus `WORKER_ALLOWED_DOMAINS`/`WORKER_DISALLOWED_DOMAINS`. The proxy binds `127.0.0.1` **by design** — the Linux `IPAddressDeny=any` / `IPAddressAllow=127.0.0.1` scope depends on it, so do not make the host configurable. The port comes from `WORKER_PROXY_PORT` (default 8118); consume the injected `HTTP_PROXY` URL rather than rebuilding it.
- Embedded workers are subprocesses under `./workspaces/{agentId}/` with `WORKSPACE_DIR`. Linux hosts with a usable user systemd wrap them in `systemd-run --user --scope`; other hosts run them unwrapped unless `LOBU_REQUIRE_WORKER_SANDBOX=1`.
- Nix packages (agent + connector-contributed, unioned at resolve time; legacy skill-level packages are ignored) are portable across runtimes. The built-in runtime wraps the worker spawn in `nix-shell -p`; remote runtimes get the same set as the SIGNED `nixPackages` worker-token claim and `/internal/runtime/exec` provisions it via the provider's optional `ensurePackages` before the first command. Rules when touching this: the list comes from the token claim and NEVER the request body (same as `allowedDomains` — the worker is the sandbox-ee); every name goes through `nixPackageAttrRef` before it reaches a command line; idempotence is a marker file in the sandbox filesystem, never a gateway Map (another replica handles the next message); and provisioning degrades honestly — a failed install or a provider with no `ensurePackages` leaves the CLI absent and says so in the exec result, it never fails the turn. Remote provisioning needs the nix substituter hosts in the sandbox network policy, added gateway-side only when there is a validated package set.

## Local dev and validation
- Prereqs: Bun, supported Node per package engines, and Postgres+pgvector via `DATABASE_URL`. `./scripts/setup-dev.sh` provisions local Postgres where needed.
- `make dev` uses shared brew Postgres with one DB per branch. `LOBU_EMBEDDED=1 make dev` / `make dev-embedded` uses embedded per-worktree Postgres.
- Parallel worktrees use `.env.local` for non-default `PORT`/`WORKER_PROXY_PORT`; do not `git switch` while a dev server runs. Read your worktree's `PORT` from `.env.local` — it is not 8787.
- Smoke a booted server: `curl -s localhost:$PORT/api/health` (readiness is `/health/ready`). The SPA is pathless at `:$PORT`; the agent API is under `:$PORT/lobu`. "It booted" is not "it works" — drive the path you changed.
- Validation: the root gates (`make pre-pr` + `make review`, see root `AGENTS.md`) plus the relevant server `bun test` / `make test-integration` suites.

## Slackbot MCP integration
- Slackbot is an MCP client. A Slack app exposes tools/resources only with `mcp:connect` bot scope plus an `mcp_servers` manifest block; after scope changes, reinstall the app.
- Manifest template: `config/slack-app-manifest.self-install.json`. Manage it with `scripts/slack-manifest.ts` (`print|validate|update`) and Slack config credentials.
- `/mcp` is mounted at app root, not under `/lobu`. Manifest MCP URL is `<origin>/mcp`; webhook/slash/OAuth URLs keep the `/lobu` base. Do not change this to `/lobu/mcp`.
- OAuth/redirect/`WWW-Authenticate` URLs come from `PUBLIC_GATEWAY_URL` cached at boot. For Slack cloud flows this must be a public HTTPS origin; update env and restart when switching origins.
- Local public dev endpoint is Tailscale Funnel to gateway `:8787`; verify `/mcp` returns auth challenge, not 404.
# Agent worker package agent rules

Read root `AGENTS.md` first. This package owns agent execution and Lobu integration.

## Boundaries
- Agent workers talk only to the gateway/agent APIs. They must not gain platform-specific knowledge or receive real credentials.
- Workers may receive `lobu_secret_<uuid>` placeholders; the gateway proxy performs credential substitution at egress.
- Worker sessions persist under `./workspaces/{agentId}/`.

## Providers, MCP, and tools
- Resolve model refs through provider settings/catalog data passed by the gateway. Do not hardcode provider credentials, base URLs, or model lists in worker code.
- Provider API keys are injected into in-memory auth storage only for the running session; do not write provider auth to disk.
- If the selected provider changes for a persisted session, preserve a system note and reset incompatible provider state rather than mixing provider histories.
- Workers discover MCP tools at startup and call them through the gateway proxy using JWT.
- MCP auth tools (`auth login|check|logout`) route through the gateway/device-auth flow; worker code should refresh MCP context after auth changes.
- Built-in Lobu tools are registered in `src/runtime/custom-tools.ts` and use snake_case names.
- Past channel conversation is read through `search_memory`, which also scans `channel_messages`.

## Network and runtime
- Worker subprocesses reach the network through the gateway proxy on `127.0.0.1` (loopback is required by the Linux `IPAddressDeny` scope), port from `WORKER_PROXY_PORT` (default 8118). Consume the injected `HTTP_PROXY` URL rather than rebuilding it from a hardcoded port.
- `WORKER_ALLOWED_DOMAINS`: empty = no network by default; exact domains or `.wildcard`; `*` means allow all and is not for prod; combine with `WORKER_DISALLOWED_DOMAINS` for blocklist mode.
- Linux prod adds kernel network denial except loopback; risky domains may route through the LLM egress judge.
- SDK sandbox loads the per-Node-major `isolated-vm` optional native build dynamically in `sandbox/run-script.ts`; keep that exception unless there is a static equivalent.

## Validation
- After editing `packages/agent-worker/*`, run `make clean-workers`.
- Validation: the root gates (`make pre-pr` + `make review`, see root `AGENTS.md`) plus targeted worker tests.
# Connector SDK package agent rules

Read root `AGENTS.md` first. This package is the contract every connector compiles against: `ConnectorRuntime`, the source primitives (`file-source`, `acl-source`, `http-client`), identity normalization, pagination/retry/scoring helpers, and the browser automation layer. Built-in connector *implementations* live in `packages/connectors`; user-authored ones are compiled from project directories. Keep this package generic — it serves both.

## Boundaries
- This is a published contract consumed by external connectors. A breaking change to an exported type or runtime method breaks compiled connectors in the wild — additive changes only unless a migration is planned.
- `playwright` is a **peer** dependency aliased to patchright, and it is optional. Never make a top-level import of it a hard requirement of the package entrypoint; browser code must stay reachable only from the browser paths.
- `url-guards.ts` provides SSRF and domain checks; call them before outbound requests whose URL is caller- or content-controlled. `createHttpClient` handles auth and retries, but it does not validate URLs.

## Browser automation
- The stealth layer exists to look like a real browser; patchright (not vanilla playwright) is deliberate. Do not "fix" the alias in `package.json` — install revision and runtime revision must match, or Chromium fails to launch.
- `launcher.ts` distinguishes two failure modes: a `PLAYWRIGHT_BROWSERS_PATH` mismatch versus an unresolvable package. When a launch fails, read which error you got before debugging — see `docs/GOTCHAS.md`, "Browser & connectors", for the Docker/install invariants behind it.
- CDP (`cdp.ts`, `cdp-page.ts`) and the extension scrape paths (`extension-dom-scrape.ts`, `extension-network.ts`) are different backends with different auth stories. Extension paths reach the user's real logged-in sessions; local Playwright/CDP does not.

## Package-specific traps
- This package is **biome-excluded** (`config/biome.config.json`). Never run biome on it — edit surgically, matching each file's existing style. See `docs/GOTCHAS.md`, "Formatting & lint".
- A new workspace package that imports this SDK must appear after connector-sdk in all three build lists — see `docs/GOTCHAS.md`, "Build & typecheck".

## Validation
- Validation: the root gates (`make pre-pr` + `make review`, see root `AGENTS.md`) plus targeted SDK tests. Browser changes need a real connector run, not just a unit test — a green mock proves nothing about Chromium launch.

