      // Record the applied change-set as a FIRST-CLASS event on the run — even
      // for fully-auto promotions. The diff is a property of the run, not of the
      // approval flow: a watcher run that auto-applied 100 entity changes still
      // shows exactly what it changed. Rides the window tx (it describes writes
      // that just committed on this same tx) and is scoped to the run + the
      // entities it touched, so the run view and the entity views both resolve it.
      if (promote.changes.length > 0 && watcherRunId && Number.isFinite(watcherRunId)) {
        const createdCount = promote.changes.filter((c) => c.kind === 'created').length;
        const updatedCount = promote.changes.length - createdCount;
        await insertEvent(
          {
            entityIds: promote.changes.map((c) => c.entityId),
            organizationId: watcherOrgId,
            originId: `run_${watcherRunId}_changeset`,
            title: `Behavior applied ${createdCount} new + ${updatedCount} updated`,
            content: `This run created ${createdCount} and updated ${updatedCount} entities.`,
            semanticType: 'change_set',
            runId: watcherRunId,
            metadata: {
              kind: 'watcher_change_set',
              window_id: windowId,
              watcher_id: Number(watcherId),
              created_count: createdCount,
              updated_count: updatedCount,
              changes: promote.changes,
            },
            createdBy: watcherCreatedBy,
          },
          { sql: tx }
        );
      }
    }

      const entityRows =
        eIds.length > 0
          ? await sql`
              SELECT e.id, e.name, et.slug AS entity_type, e.metadata
              FROM entities e
              JOIN entity_types et ON et.id = e.entity_type_id
              WHERE e.id = ANY(${`{${eIds.join(',')}}`}::bigint[])
            `
          : [];

      // Fetch watcher name from version, slug from template (pre-consolidation)
      const watcherMeta = await sql`
        SELECT w.id, COALESCE(wv.name, 'watcher-' || w.id) as name,
               COALESCE(w.slug, 'watcher-' || w.id) as slug
        FROM watchers w
        LEFT JOIN watcher_versions wv ON w.current_version_id = wv.id
        WHERE w.id = ${result.behavior_id}
      `;

      const reactionContext = {
        extracted_data: cleanedExtractedData,
        entities: entityRows.map((e: any) => ({
          id: Number(e.id),
          name: e.name as string,
          entity_type: e.entity_type as string,
          metadata: (e.metadata ?? {}) as Record<string, unknown>,
        })),
        window: {
          id: result.window_id,
          run_id: watcherRunId,
          behavior_id: Number(result.behavior_id),
          window_start: result.window_start,
          window_end: result.window_end,
          granularity: timeGranularity,
          content_analyzed: batchContentIds.length,
        },
        behavior: {
          id: Number(result.behavior_id),
          slug: (watcherMeta[0]?.slug ?? `watcher-${result.behavior_id}`) as string,
          name: (watcherMeta[0]?.name ?? `watcher-${result.behavior_id}`) as string,
          version: Number(row.watcher_version ?? 1),
        },
        organization_id: orgId,
        organization_slug: String(row.organization_slug),
      };

      const MAX_ATTEMPTS = 3;
      for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
        const execResult = await executeReaction({
          compiledScript: row.reaction_script_compiled as string,
          context: reactionContext,
          env: env as Record<string, string | undefined>,
        });

        await trackWatcherReaction({
          organizationId: orgId,
          watcherId: Number(result.behavior_id),
          windowId: result.window_id,
          reactionType: 'script_execution',
          toolName: 'reaction_executor',
          toolArgs: { attempt },
          toolResult: { success: execResult.success, error: execResult.error },
        });

        if (execResult.success) {
          reactionStatus = 'success';
          logger.info(
            {
              watcher_id: result.behavior_id,
              window_id: result.window_id,
              attempt,
            },
            'Reaction script executed successfully (inline)'
          );
          break;
        }
        if (attempt < MAX_ATTEMPTS) {
          logger.warn(
            { watcher_id: result.behavior_id, attempt, error: execResult.error },
            'Reaction script failed, retrying...'
          );
          await new Promise((r) => setTimeout(r, 1000));
        } else {
          reactionStatus = 'failed';
          reactionError = execResult.error;
          logger.error(
            { watcher_id: result.behavior_id, error: execResult.error },
            'Reaction script failed after all retries'
          );
        }
      }
    }
  } catch (err) {
    reactionStatus = 'failed';
    reactionError = getErrorMessage(err);
    logger.warn({ err }, '[manage_behaviors] Failed to execute reaction script');
	return (
		row.connection_display_name ??
		row.connector_key ??
		`Run #${row.id}`
	);
}

function collapseKeyForRun(row: {
	run_type: string;
	connection_id: number | null;
	watcher_id: number | null;
	connector_key: string | null;
	feed_id: number | null;
}): string | null {
	if (row.run_type === "sync" || row.run_type === "action") {
		if (row.connection_id != null) return `conn:${row.connection_id}`;
		if (row.connector_key && row.feed_id != null) {
			return `feed:${row.connector_key}:${row.feed_id}`;
		}
		return null;
	}
	if (row.run_type === "behavior" && row.watcher_id != null) {
		return `watcher:${row.watcher_id}`;
	}
	return null;
}

/** Adjacent collapse — same rules as Owletto client (oldest→newest input). */
export function collapseAdjacentActivityCards(items: RawCard[]): RawCard[] {
	if (items.length <= 1) return items;
	const out: RawCard[] = [];
	let i = 0;
	while (i < items.length) {
		const head = items[i]!;
		if (
			head.kind === "notification" ||
					interactionType === "approval" &&
					interactionStatus != null &&
					(ENTITY_CHANGE_ACTION_KEYS as readonly string[]).includes(
						String(n.approval_action_key ?? ""),
					);
				raw.push({
					id: `n:${n.id}`,
					kind: "notification",
					title: String(n.title ?? "Notification"),
					body: n.body != null ? String(n.body) : null,
					at: created,
					atMs: Number.isFinite(atMs) ? atMs : 0,
					status: type,
					count: 1,
					href: resolveNotifHref(opts.ownerSlug, n),
					unread: n.is_read === false || n.is_read === "f",
					notification_id: Number(n.id),
					run_id: Number.isFinite(approvalRunId) ? approvalRunId : undefined,
					interaction_type: interactionStatus != null ? interactionType : undefined,
					interaction_status: interactionStatus,
					interaction_inline: interactionInline || undefined,
					collapseKey: null,
					itemsCollected: null,
				});
			}
		}
	}

	if (includeRuns) {
		const runKinds = kindFilter
			? USER_FACING_RUN_TYPES.filter((k) => kindFilter.has(k) || kindFilter.has("run"))
			: [...USER_FACING_RUN_TYPES];
		if (runKinds.length > 0) {
			const sql = getDb();
			// When agent-scoped, restrict to that agent's Behavior runs. The join to
			// `watchers` already exposes `w.agent_id`; a non-null agentId turns the
			// LEFT JOIN into an effective inner filter (runs with no watcher, i.e.
			// bare syncs/actions, are dropped — they aren't agent-owned).
			const agentFilter = opts.agentId
				? sql`AND w.agent_id = ${opts.agentId}`
				: sql``;
			const rows = (await sql`
        SELECT r.id, r.run_type, r.watcher_id, r.connection_id, r.feed_id,
               r.connector_key, r.action_key AS operation_key,
               r.approval_status, r.status, r.error_message, r.items_collected,
               r.created_at, r.completed_at,
               f.feed_key, f.display_name AS feed_display_name,
               c.display_name AS connection_display_name,
               w.name AS watcher_name, w.agent_id
        FROM runs r
        LEFT JOIN feeds f ON f.id = r.feed_id
        LEFT JOIN connections c ON c.id = r.connection_id
        LEFT JOIN watchers w ON w.id = r.watcher_id
        WHERE r.organization_id = ${opts.organizationId}
          AND r.run_type = ANY(${pgTextArray(runKinds)}::text[])
          ${agentFilter}
        ORDER BY r.created_at DESC, r.id DESC
        LIMIT 60
      `) as unknown as Array<{
				id: number;
				run_type: string;
				watcher_id: number | null;
				connection_id: number | null;
				feed_id: number | null;
				connector_key: string | null;
				operation_key: string | null;
		interactionError:
			(extraMetadata.error_message as string | undefined) ?? null,
		supersedesEventId: Number(orig.id),
		// The durable identity (FK → user); set on the first decision event and
		// preserved down the chain.
		createdBy: reviewedById,
		metadata: {
			...priorMetadata,
			status,
			...(reviewedById ? { reviewed_by_id: reviewedById } : {}),
			...(reviewedByName ? { reviewed_by_name: reviewedByName } : {}),
				...(extraMetadata.output
					? { action_output: extraMetadata.output }
					: {}),
			...(extraMetadata.error_message
				? { error_message: extraMetadata.error_message }
				: {}),
			...extraMetadata,
			// Superseding copies the prior metadata forward, so a durable approval
			// written before the Behaviors rename (#2034) would keep minting NEW
			// rows carrying `resourceKind: "watcher"` every time it is resolved.
			// Canonicalize on write: history keeps whatever it recorded, but nothing
			// emitted from here reintroduces the pre-rename value. Must stay below
			// both spreads so neither the prior row nor a caller can restore it.
			...(priorMetadata.resourceKind === "watcher" ||
			extraMetadata.resourceKind === "watcher"
				? { resourceKind: "behavior" }
				: {}),
		},
		authorName: orig.author_name ?? null,
		},
		{ sql },
	);

	return Number(nextEvent.id);
}

