   309	 * Throws on any validation failure.
   310	 */
   311	export function validateAndScopeQuery(
   312	  rawSql: string,
   313	  organizationId: string,
   314	  options?: {
   315	    safeColumns?: Map<string, ColumnDef[]>;
   316	    /**
   317	     * Tables the caller may NOT reference (rejected even though they're in the
   318	     * global allowlist). Used to keep auth/identity tables (oauth_tokens,
   319	     * oauth_clients, user) admin-only when a non-admin runs query_sql /
   320	     * metric_series. Omit for admin / server-internal callers (full access).
   321	     */
   322	    restrictedTables?: ReadonlySet<string>;
   323	    /**
   324	     * The requesting user. Threaded into the events CTE so connection-sourced
   325	     * rows are filtered to org-visible connections or this user's own private
   326	     * ones (per-user visibility). Omit for service/headless callers — null
   327	     * yields org-visible-only (fail-closed for private data).
   328	     */
   329	    userId?: string | null;
   330	  }
