   789	// ============================================
   790	// Validation
   791	// ============================================
   792	
   793	/**
   794	 * Inspect a SELECT/WITH query's top-level projection and report whether it
   795	 * surfaces an `id` column.
   796	 *
   797	 * Watcher-mode content aggregation keys every row by `row.id` (see
   798	 * queryContentData in get_content.ts) and the signed window_token only carries
   799	 * those numeric ids. A source query that omits `id` (e.g. `SELECT origin_id,
   800	 * payload_text FROM events`) therefore produces zero content_ids — which makes
   801	 * complete_window silently report `content_linked: 0` and skip the reaction
   802	 * even though the agent received the rows. We catch that at save time instead.
   803	 *
   804	 * A projection "has id" if it contains a `*` star (bare or table-qualified),
   805	 * a bare `id` column reference, or any column aliased `AS id`.
   806	 *
   807	 * Returns true on any parse failure: this is a best-effort guard, not a
   808	 * security control, and we never want a parser edge case to block a save.
   809	 */
   810	export function queryProjectsIdColumn(query: string): boolean {
   811	  try {
   812	    const root = parseRoot(query);
   813	    // Treat any shape we can't analyze (parse failure, non-SELECT) as "has id"
   814	    // so we never block a save on a parser edge case.
   815	    if (!root || ast.getExprType(root) !== 'select') return true;
   816	    const projection = (ast.getExprData(root) as { expressions?: unknown[] }).expressions;
   817	    if (!Array.isArray(projection)) return true;
   818	
   819	    for (const item of projection as SqlNode[]) {
   820	      const itemType = ast.getExprType(item);
   821	      // Star projection: `*` or `alias.*`
   822	      if (itemType === 'star' || ast.isStar?.(item)) return true;
   823	      if (itemType === 'alias') {
   824	        const d = ast.getExprData(item) as Record<string, unknown>;
   825	        if (identName(d.alias)?.toLowerCase() === 'id') return true; // ... AS id
   826	        const inner = (d.this ?? d.expr) as SqlNode | undefined;
   827	        if (inner && (ast.getExprType(inner) === 'star' || ast.isStar?.(inner))) return true;
   828	      } else if (itemType === 'column') {
   829	        if (identName((ast.getExprData(item) as Record<string, unknown>).name)?.toLowerCase() === 'id')
   830	          return true; // bare `id`
   831	      }
   832	    }
   833	    return false;
   834	  } catch {
   835	    return true;
   836	  }
   837	}
