   839	/**
   840	 * Validate a data source query.
   841	 * Checks: SELECT/WITH prefix, forbidden ops, SQL syntax, schema-qualified refs.
   842	 * When `parse` is true (save-time), also validates syntax and table refs.
   843	 */
   844	export function validateDataSourceQuery(name: string, query: string, parse = false): void {
   845	  const trimmed = query.trim();
   846	  if (!/^(SELECT|WITH)\b/i.test(trimmed)) {
   847	    throw new Error(`Data source '${name}': query must start with SELECT or WITH`);
   848	  }
   849	  if (FORBIDDEN_OPS.test(trimmed)) {
   850	    throw new Error(`Data source '${name}': query contains forbidden operations`);
   851	  }
   852	  if (parse) {
   853	    try {
   854	      const res = parseSql(stripPlaceholders(trimmed), Dialect.PostgreSQL);
   855	      if (!res.success) throw new Error(res.error ?? 'could not parse query');
   856	      // Reject auth/identity tables at save time so a template that would only
   857	      // be masked at runtime fails fast with a clear error. (Runtime masking via
   858	      // SAFE_COLUMN_DEFS is the enforcement; this is early, defense-in-depth
   859	      // feedback.) Column-level allowlisting is intentionally NOT applied here —
   860	      // data sources legitimately reference entity-type slugs (unknown tables).
   861	      const refs = extractTableRefs(trimmed);
   862	      const restricted = refs.filter((t) => ADMIN_ONLY_QUERYABLE_TABLES.has(t));
