   865	          `references admin-only table(s): ${[...new Set(restricted)].join(', ')}`
   866	        );
   867	      }
   868	    } catch (err) {
   869	      throw new Error(`Data source '${name}': ${getErrorMessage(err)}`);
   870	    }
   871	  }
   872	}
