/**
 * Shared Behavior Types
 *
 * Single source of truth for behavior-related types used across
 * backend tools, utils, and frontend components. TypeBox-first: each type is
 * derived from its schema via `Static<>`, so the runtime JSON Schema (surfaced
 * as MCP tool `outputSchema`) and the TS type cannot drift.
 */

import { type Static, Type } from '@sinclair/typebox';
import {
  BehaviorTriggerSchema,
  type BehaviorTrigger,
  BehaviorSourceSchema,
  type BehaviorSource,
  BehaviorKeyingConfigSchema,
  type BehaviorKeyingConfig,
} from '@lobu/core/contracts/tools/manage-behaviors';

type BehaviorSource = BehaviorSource;
const BehaviorSourceSchema = BehaviorSourceSchema;

export {
  BehaviorTriggerSchema,
  type BehaviorTrigger,
  BehaviorSourceSchema as BehaviorSourceSchema,
  type BehaviorSource,
};

