import { Button } from "@/components/ui/button";
import { BehaviorRunThread } from "@/components/behaviors/behavior-run-thread";

/**
 * Renders the SAME content component the dedicated page renders, mounted inside
 * the peek pane — never a duplicate. `parsePeekHref` already gated this to
 * previewable destinations (behavior runs, memory events); other activity items
 * (connector detail) navigate to their dedicated page instead of opening the
 * pane, so we always have a known destination here.
 */
export function PeekPaneContent({
	href,
	runId,
}: {
	href: string;
	runId?: number;
}) {
	const dest = parsePeekHref(href);
	if (!dest) return null;

	if (dest.kind === "memory") {
		return <MemoryEventsPeek owner={dest.owner} runId={runId ?? dest.runId} />;
	}

	// Behavior destination — when we have a specific runId, show just that run's
	// transcript, not the full behavior page (tabs, all runs, etc.).
	if (runId) {
		return (
			<BehaviorRunThread
				agentId={dest.agentId}
				behaviorId={dest.behaviorId}
				ownerSlug={dest.owner}
				runId={runId}
			/>
		);
	}
	return (
		<BehaviorPeek
			owner={dest.owner}
			agentId={dest.agentId}
			behaviorId={dest.behaviorId}
			initialView={dest.view ?? "activity"}
			runId={dest.runId}
		/>
	);
}

/**
 * Behavior content in the peek pane. The Edit toggle is local state (not a router
 * Link) so it flips the pane's surface without navigating the host page.
 */
function BehaviorPeek({
	owner,
	agentId,
	behaviorId,
	initialView,
	runId,
}: {
	owner: string;
	agentId: string;
	behaviorId: string;
	initialView: BehaviorBehaviorView;
	runId?: number;
}) {
	const [view, setView] = useState<BehaviorBehaviorView>(initialView);
	const isEditing = view === "definition";
	return (
		<div className="space-y-2">
			<div className="flex justify-end">
				<Button
					type="button"
					variant="ghost"
					size="sm"
					className="h-8 gap-1.5 text-muted-foreground hover:text-foreground"
					onClick={() => setView(isEditing ? "activity" : "definition")}
				>
					{isEditing ? (
						"Done"
					) : (
						<>
							<Pencil className="h-3.5 w-3.5" />
							Edit
						</>
					)}
				</Button>
			</div>
			<AgentBehaviorBehaviorContent
				owner={owner}
				agentId={agentId}
				behaviorId={behaviorId}
				view={view}
				runId={runId}
				onDone={() => setView("activity")}
			/>
		</div>
	);
}
