          typeof a === 'string'
            ? a
            : ((a as { name?: string; value?: string })?.name ??
              (a as { value?: string })?.value);
        if (typeof name === 'string' && name) out.add(name.toLowerCase());
      } catch {
        // skip malformed projection item
      }
    }
  } catch {
    // unparseable → no aliases; validator errors stand
  }
  return out;
}

