  UPDATE public.behaviors b
  SET status = 'archived', updated_at = current_timestamp
  WHERE b.status = 'active'
    AND b.organization_id = OLD.organization_id
    AND b.agent_id = OLD.id;
  RETURN OLD;
END
$archive$;

