function behaviorKeys(value: unknown, path = "$"): string[] {
	if (Array.isArray(value)) {
		return value.flatMap((item, index) => behaviorKeys(item, `${path}[${index}]`));
	}
	if (value === null || typeof value !== "object") return [];
