/**
 * Device Behavior claim detection for the Chrome worker poll lane.
 *
 * Server enqueues run_type="behavior" (legacy wire "behavior"). Chrome is a
 * connector/action worker only — Mac Owletto executes Behaviors via a local
 * CLI. Callers must fail closed through /complete-behavior, not /complete.
 *
 * @param {{ run_type?: string | null } | null | undefined} run
 * @returns {boolean}
 */
export function isDeviceBehaviorRun(run) {
  const t = run?.run_type;
  return t === "behavior" || t === "behavior";
}
        }
        // Behavior runs carry no connector_key, so fall through to the operation
        // and finally run_type rather than reporting an empty label.
        onJobClaimed?(job.operation_key ?? job.connector_key ?? job.run_type ?? "operation")

        let heartbeatBaseURL = initial.baseURL
        let heartbeatAccessToken = effectiveToken
        let heartbeatTask = Task.detached {
            let heartbeatClient = WorkerClient(baseURL: heartbeatBaseURL, accessToken: heartbeatAccessToken)
            while !Task.isCancelled {
                try? await Task.sleep(for: .seconds(60))
                if Task.isCancelled { break }
                try? await heartbeatClient.heartbeat(workerId: workerId, runId: job.run_id)
            }
        }
        defer { heartbeatTask.cancel() }

        // Behavior / behavior runs (lobu#798): branch BEFORE the connector
        // switch. Server wire value is `run_type: "behavior"` (DB/queue);
        // older comments/docs said "behavior". Accept both so pinned Behaviors
        // are not left pending forever.
        // Envelope: `payload: { behavior, event, context }`, no connector_key.
        // Hand off to BehaviorDispatcher → local CLI → complete-behavior.
        if job.run_type == "behavior" || job.run_type == "behavior" {
            guard let raw else {
                // Behavior-run failures (including this one) must go through
                // complete-behavior so the row is consistent with the rest of
                // the Behavior lifecycle on the server.
                _ = try await worker.completeBehaviorRun(
                    workerId: workerId, runId: job.run_id,
                    output: "", error: "Behavior job missing payload envelope",
                    durationMs: 0, exitCode: nil, exitSignal: nil, exitReason: "error_message"
                )
                return CycleResult(claimedJob: true, itemsStreamed: 0, connectorKey: nil, runId: job.run_id)
            }
            let decoder = JSONDecoder()
            let behaviorJob: BehaviorJob
            do {
    let id: Int
    let connector_key: String?
    let connector_name: String?
    let name: String?
    let status: String?
    let event_count: Int?
}

struct LobuConnectionsResponse: Decodable {
    let connections: [LobuConnection]
}

/// Behavior row as projected by `GET /api/<orgSlug>/behaviors` (manage_behaviors
/// list). Only the fields the menubar Behaviors section needs are decoded —
/// server adds more.
///
/// Wire names after the behavior→behavior rename: `behavior_id`,
/// `behavior_run_id`, `behavior_run_status`. Older gateways used `behavior_*`;
/// decode accepts both so a stale deploy cannot empty the menubar section.
struct Behavior: Decodable, Identifiable, Equatable {
    let id: Int
    let name: String
    let status: String              // "active" | "paused" | …
    let device_worker_id: String?   // null = not pinned (we filter for this Mac)
    let last_fired_at: String?      // ISO-8601 or nil if never fired

    cachedCanDisableTriggers = false;
  }
  return cachedCanDisableTriggers;
}

/**
 * Patch check constraints that the baseline migration defines too narrowly.
 * These ALTER statements are idempotent (drop + re-add).
 */
async function fixSchemaConstraints(db: postgres.Sql): Promise<void> {
  try {
    // runs.run_type needs the connector lanes plus the lobu-queue lanes. Keep
    // this in sync with db/migrations/20260429060000_extend_runs_for_lobu_queue.sql
    // and db/migrations/20260720140000_rename_run_type_behavior_to_behavior.sql
    // (the 'behavior' lane was renamed to 'behavior').
    await db.unsafe(`
      ALTER TABLE IF EXISTS runs DROP CONSTRAINT IF EXISTS runs_run_type_check;
      ALTER TABLE IF EXISTS runs ADD CONSTRAINT runs_run_type_check
        CHECK (run_type IN (
          'sync','action','behavior','embed_backfill','auth',
          'chat_message','schedule','agent_run','internal','task'
        ));
    `);
/**
 * Behavior health surfacing (item 3, #2033).
 *
 * 3.1: manage_behaviors `list` returns a computed `health` field —
 *   `degraded` for an active behavior that missed a firing, has a stale pending
 *   run, or whose latest run failed/timed out; `healthy` otherwise.
 *
 * 3.2: getSchedulerHealth (the /health/scheduler alarm path) surfaces overdue
 *   active behaviors and stuck-pending behavior runs in `issues[]` — previously
 *   it filtered run_type='sync' ONLY, so behaviors were invisible to alerting.
 *
 * Note on run_type: the behavior→behavior rename (#2034) migrated the
 * runs.run_type enum value 'behavior'→'behavior', so behavior runs now carry
 * run_type='behavior' and the CHECK constraint rejects 'behavior'. The
 * `behavior_id` COLUMN and the `behaviors` table stay (internal seam). These
 * tests insert run_type='behavior' to match the migrated schema + the code
 * under test.
 */

import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";
import type { Env } from "../../index";
