BEGIN
  UPDATE public.behaviors
  SET last_run_completed_at = GREATEST(
    COALESCE(last_run_completed_at, NEW.completed_at),
    NEW.completed_at
  )
  WHERE id = NEW.behavior_id
    AND organization_id = NEW.organization_id;
  RETURN NEW;
END;
$$;

