kind: Job
metadata:
  name: {{ include "lobu.fullname" . }}-migrate
  labels:
    {{- include "lobu.labels" . | nindent 4 }}
  annotations:
    "helm.sh/hook": pre-install,pre-upgrade
    "helm.sh/hook-delete-policy": before-hook-creation,hook-succeeded
spec:
  backoffLimit: 1
  template:
    metadata:
      labels:
        {{- include "lobu.selectorLabels" . | nindent 8 }}
        app.kubernetes.io/component: migrate
    spec:
      restartPolicy: Never
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      containers:
        - name: migrate
          image: {{ include "lobu.appImage" . }}
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          command:
            - /bin/bash
            - -ec
            - |
              {{- if .Values.releaseGates.databasePreflight.enabled }}
              echo "checking migration database connectivity"
              node --input-type=module <<'NODE'
              import postgres from "postgres";

              const databaseUrl = process.env.DATABASE_URL;
              const timeoutSeconds = Number(process.env.DB_PREFLIGHT_TIMEOUT_SECONDS || 10);

              if (!databaseUrl) {
                console.error("ERROR: DATABASE_URL not set");
                process.exit(1);
              }

              const sql = postgres(databaseUrl, {
                max: 1,
                connect_timeout: timeoutSeconds,
                idle_timeout: 1,
                onnotice: () => {},
              });

              try {
                const rows = await sql`select current_database() as database`;
                console.log(`migration database preflight passed (${rows[0]?.database ?? "unknown"})`);
              } catch (error) {
                console.error("ERROR: migration database preflight failed");
                console.error(error instanceof Error ? error.message : String(error));
                process.exit(1);
              } finally {
                await sql.end({ timeout: 1 }).catch(() => {});
              }
              NODE
              {{- end }}
              exec /app/start.sh migrate
          env:
            {{- range $key, $value := .Values.app.env }}
            - name: {{ $key }}
              value: {{ $value | quote }}
            {{- end }}
            {{- if .Values.releaseGates.databasePreflight.enabled }}
            - name: DB_PREFLIGHT_TIMEOUT_SECONDS
              value: {{ .Values.releaseGates.databasePreflight.timeoutSeconds | quote }}
            {{- end }}
            {{- if .Values.migrations.database.existingSecret }}
            {{- if .Values.migrations.database.usePooler }}
            - name: DB_USER
              valueFrom:
                secretKeyRef:
                  name: {{ .Values.migrations.database.existingSecret }}
                  key: username
            - name: DB_PASS
              valueFrom:
                secretKeyRef:
                  name: {{ .Values.migrations.database.existingSecret }}
                  key: password
            - name: DATABASE_URL
              value: "REDACTED .Values.migrations.database.poolerService }}:5432/{{ .Values.migrations.database.name }}?sslmode=disable"
            {{- else }}
            - name: DATABASE_URL
              valueFrom:
                secretKeyRef:
                  name: {{ .Values.migrations.database.existingSecret }}
                  key: {{ .Values.migrations.database.existingSecretKey }}
            {{- end }}
            {{- end }}
          {{- if .Values.secretName }}
          envFrom:
            - secretRef:
                name: {{ .Values.secretName }}
          {{- end }}
{{- end }}
# Default values for lobu chart

# Global settings
nameOverride: ""
fullnameOverride: ""

# Image settings (shared between app, worker, and embeddings)
image:
  registry: ghcr.io
  repository: lobu-ai/lobu
  pullPolicy: Always
  # Tag defaults to chart appVersion
  tag: "latest"

imagePullSecrets:
  - name: ghcr-credentials

# App deployment settings (API backend)
app:
  replicaCount: 1
  # Recreate: the old pod fully terminates before the new one starts, so at most
  # ONE server version is ever live. This is a correctness requirement, not just a
  # single-replica convenience — write-gate policy migrations add scope columns
  # (e.g. operation_key) whose write predicates only the NEW code carries. Under
  # RollingUpdate an old pod could serve a scope-blind UPDATE/DELETE concurrently
  # with the migrated schema and clobber a freshly-written finer-scoped policy row
  # (a persistent fail-open). Recreate removes the two-version overlap window. With
  # replicaCount 1 there is no availability cost vs RollingUpdate (never >1 serving
  # pod anyway). `workspaces.enabled: true` (legacy RWO path) already pinned this.
  strategy:
    type: Recreate

  resources:
    requests:
      # The app pod embeds the orchestrator AND spawns agent-worker subprocesses
